{% comment %} ── Gamme Touch / Touch XL — Hero "backlit" + bandeau de confiance ── {% endcomment %}
<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&display=swap" rel="stylesheet">
<style>
  .tc-scope { --tc-ink:#05080f; --tc-ink2:#0a1120; --tc-surf:#111c30; --tc-line:rgba(255,255,255,.10);
    --tc-txt:#eaf0fb; --tc-mut:#93a2bd; --tc-blue:#4da3ff; --tc-gold:#f5b544; }
  .tc-hero * { box-sizing:border-box; margin:0; padding:0; }
  .tc-hero { position:relative; overflow:hidden; background:#05080f; color:#eaf0fb;
    font-family:'Poppins',-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;
    padding:96px 24px 104px; }
  .tc-hero::before { content:''; position:absolute; inset:0;
    background:
      radial-gradient(900px 480px at 78% 30%, rgba(77,163,255,.22), transparent 62%),
      radial-gradient(700px 420px at 12% 82%, rgba(245,181,68,.12), transparent 60%);
    pointer-events:none; }
  .tc-hero::after { content:''; position:absolute; inset:0; opacity:.35; pointer-events:none;
    background-image:linear-gradient(rgba(255,255,255,.045) 1px, transparent 1px),
                     linear-gradient(90deg, rgba(255,255,255,.045) 1px, transparent 1px);
    background-size:64px 64px;
    -webkit-mask-image:radial-gradient(circle at 50% 40%, #000 0%, transparent 78%);
            mask-image:radial-gradient(circle at 50% 40%, #000 0%, transparent 78%); }
  .tc-hero-inner { position:relative; z-index:2; max-width:1200px; margin:0 auto;
    display:grid; grid-template-columns:1.05fr .95fr; gap:56px; align-items:center; }
  .tc-eyebrow { display:inline-flex; align-items:center; gap:10px; font-size:11px; font-weight:600;
    letter-spacing:.20em; text-transform:uppercase; color:#9fb6da; margin-bottom:22px; }
  .tc-eyebrow::before { content:''; width:34px; height:1px; background:linear-gradient(90deg,var(--tc-blue),transparent); }
  .tc-h1 { font-size:clamp(34px,4.6vw,58px); font-weight:600; line-height:1.05; letter-spacing:-.03em; margin-bottom:20px; }
  .tc-h1 em { font-style:normal; background:linear-gradient(100deg,#4da3ff 0%,#8fd0ff 45%,#f5b544 100%);
    -webkit-background-clip:text; background-clip:text; color:transparent; }
  .tc-lead { font-size:16.5px; line-height:1.65; color:#a9b8d2; max-width:520px; margin-bottom:30px; font-weight:300; }
  .tc-models { display:flex; gap:10px; flex-wrap:wrap; margin-bottom:32px; }
  .tc-chip { display:inline-flex; align-items:baseline; gap:8px; padding:9px 16px; border-radius:8px;
    background:rgba(255,255,255,.05); border:1px solid rgba(255,255,255,.12); font-size:13px; font-weight:500; }
  .tc-chip b { font-weight:600; letter-spacing:.04em; }
  .tc-chip.is-blue b { color:#7cbcff; } .tc-chip.is-gold b { color:#ffcd72; }
  .tc-chip span { font-size:12px; color:#8fa1bd; font-weight:300; }
  .tc-ctas { display:flex; gap:12px; flex-wrap:wrap; }
  .tc-btn { display:inline-flex; align-items:center; gap:9px; padding:15px 26px; border-radius:10px;
    font-size:14.5px; font-weight:600; text-decoration:none; transition:transform .18s, box-shadow .18s, background .18s; }
  .tc-btn svg { width:17px; height:17px; fill:none; stroke:currentColor; stroke-width:2.2; stroke-linecap:round; stroke-linejoin:round; }
  .tc-btn--main { background:linear-gradient(120deg,#2f7bff,#4da3ff); color:#fff; box-shadow:0 12px 30px rgba(47,123,255,.34); }
  .tc-btn--main:hover { transform:translateY(-2px); box-shadow:0 18px 40px rgba(47,123,255,.44); }
  .tc-btn--ghost { background:rgba(255,255,255,.06); color:#eaf0fb; border:1px solid rgba(255,255,255,.16); }
  .tc-btn--ghost:hover { background:rgba(255,255,255,.11); transform:translateY(-2px); }
  .tc-hero-visual { position:relative; }
  .tc-hero-visual img { width:100%; height:auto; display:block; border-radius:20px;
    box-shadow:0 40px 90px rgba(0,0,0,.55); }
  .tc-glow { position:absolute; inset:-8% -6%; border-radius:50%; z-index:-1; filter:blur(70px);
    background:radial-gradient(circle,rgba(77,163,255,.38),transparent 66%); }
  .tc-float { position:absolute; left:-26px; bottom:34px; display:flex; align-items:center; gap:12px;
    padding:13px 18px; border-radius:13px; background:rgba(11,18,32,.82); border:1px solid rgba(255,255,255,.13);
    backdrop-filter:blur(14px); -webkit-backdrop-filter:blur(14px); box-shadow:0 18px 40px rgba(0,0,0,.45); }
  .tc-float-dot { width:9px; height:9px; border-radius:50%; background:#3ddc97; box-shadow:0 0 0 5px rgba(61,220,151,.16); }
  .tc-float-t { font-size:13px; font-weight:600; display:block; }
  .tc-float-s { font-size:11.5px; color:#8fa1bd; font-weight:300; }

  /* bandeau de confiance : ligne fine, pas de cartes */
  .tc-trust { position:relative; z-index:2; background:#080e1a; border-top:1px solid rgba(255,255,255,.08);
    border-bottom:1px solid rgba(255,255,255,.08);
    font-family:'Poppins',-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif; }
  .tc-trust-inner { max-width:1200px; margin:0 auto; display:grid; grid-template-columns:repeat(4,1fr); }
  .tc-trust-cell { padding:26px 24px; border-left:1px solid rgba(255,255,255,.07); display:flex; gap:13px; align-items:flex-start; }
  .tc-trust-cell:first-child { border-left:0; }
  .tc-trust-cell svg { width:19px; height:19px; flex:none; margin-top:2px; fill:none; stroke:#4da3ff; stroke-width:1.9; stroke-linecap:round; stroke-linejoin:round; }
  .tc-trust-t { display:block; font-size:13.5px; font-weight:600; color:#eaf0fb; letter-spacing:-.01em; }
  .tc-trust-s { display:block; font-size:12px; color:#8093b3; font-weight:300; margin-top:2px; }

  @media (max-width:1000px) {
    .tc-hero-inner { grid-template-columns:1fr; gap:40px; }
    .tc-hero { padding:72px 20px 80px; }
    .tc-trust-inner { grid-template-columns:repeat(2,1fr); }
    .tc-trust-cell:nth-child(3) { border-left:0; }
    .tc-trust-cell:nth-child(-n+2) { border-bottom:1px solid rgba(255,255,255,.07); }
  }
  @media (max-width:560px) {
    .tc-float { left:12px; bottom:12px; }
    .tc-trust-inner { grid-template-columns:1fr; }
    .tc-trust-cell { border-left:0; border-bottom:1px solid rgba(255,255,255,.07); padding:20px; }
  }
</style>

<section class="tc-hero tc-scope">
  <div class="tc-hero-inner">
    <div>
      <span class="tc-eyebrow">Gamme Touch · AM301 &amp; AM302</span>
      <h1 class="tc-h1">L'alarme qui se pilote<br>du bout des <em>doigts</em>.</h1>
      <p class="tc-lead">Deux centrales à écran tactile, une même promesse&nbsp;: tout comprendre en un coup d'œil, tout commander en un geste. Sans abonnement, sans technicien, sans perçage.</p>
      <div class="tc-models">
        <span class="tc-chip is-blue"><b>TOUCH</b> <span>écran 4,3'' · 199,90 €</span></span>
        <span class="tc-chip is-gold"><b>TOUCH XL</b> <span>écran 7'' · 299,90 €</span></span>
      </div>
      <div class="tc-ctas">
        <a class="tc-btn tc-btn--main" href="#tc-duel">
          Comparer les 2 centrales
          <svg viewBox="0 0 24 24"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg>
        </a>
        <a class="tc-btn tc-btn--ghost" href="https://daewoo-security.fr/pages/configurateur_2">
          <svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="3"/><path d="M19.07 4.93a10 10 0 0 1 0 14.14M4.93 4.93a10 10 0 0 0 0 14.14"/></svg>
          Configurer mon système
        </a>
      </div>
    </div>
    <div class="tc-hero-visual">
      <div class="tc-glow"></div>
      <img src="https://cdn.shopify.com/s/files/1/0326/3132/4811/files/ChatGPT_Image_30_avr._2026_11_20_36.png?v=1777540859" alt="Centrale d'alarme Daewoo Touch à écran tactile" loading="eager" width="900" height="700">
      <div class="tc-float">
        <span class="tc-float-dot"></span>
        <span>
          <span class="tc-float-t">Système armé · Mode Total</span>
          <span class="tc-float-s">12 accessoires connectés</span>
        </span>
      </div>
    </div>
  </div>
</section>

<div class="tc-trust tc-scope">
  <div class="tc-trust-inner">
    <div class="tc-trust-cell">
      <svg viewBox="0 0 24 24"><polyline points="22 12 18 12 15 21 9 3 6 12 2 12"/></svg>
      <span><span class="tc-trust-t">Installation en 30 min</span><span class="tc-trust-s">Sans câblage ni perçage</span></span>
    </div>
    <div class="tc-trust-cell">
      <svg viewBox="0 0 24 24"><rect x="1" y="4" width="22" height="16" rx="2"/><line x1="1" y1="10" x2="23" y2="10"/></svg>
      <span><span class="tc-trust-t">Sans abonnement</span><span class="tc-trust-s">Application incluse à vie</span></span>
    </div>
    <div class="tc-trust-cell">
      <svg viewBox="0 0 24 24"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0 1 18 0z"/><circle cx="12" cy="10" r="3"/></svg>
      <span><span class="tc-trust-t">SAV basé en France</span><span class="tc-trust-s">Support 7j/7</span></span>
    </div>
    <div class="tc-trust-cell">
      <svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg>
      <span><span class="tc-trust-t">Garantie 2 ans</span><span class="tc-trust-s">Retour gratuit 14 jours</span></span>
    </div>
  </div>
</div>

{% comment %} ── Touch vs Touch XL : confrontation des 2 centrales + tableau comparatif ── {% endcomment %}
<link href="https://fonts.googleapis.com/css2?family=Poppins:wght@300;400;500;600;700&display=swap" rel="stylesheet">
<style>
  .tcd * { box-sizing:border-box; margin:0; padding:0; }
  .tcd { font-family:'Poppins',-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif;
    background:#05080f; color:#eaf0fb; padding:96px 24px 0; position:relative; overflow:hidden; }
  .tcd::before { content:''; position:absolute; top:0; left:50%; transform:translateX(-50%);
    width:1px; height:100%; background:linear-gradient(180deg,transparent,rgba(255,255,255,.10) 18%,rgba(255,255,255,.10) 72%,transparent); }
  .tcd-inner { position:relative; z-index:2; max-width:1200px; margin:0 auto; }
  .tcd-head { text-align:center; margin-bottom:56px; }
  .tcd-eyebrow { display:inline-flex; align-items:center; gap:10px; font-size:11px; font-weight:600;
    letter-spacing:.2em; text-transform:uppercase; color:#9fb6da; margin-bottom:18px; }
  .tcd-eyebrow::before,.tcd-eyebrow::after { content:''; width:30px; height:1px; background:rgba(255,255,255,.22); }
  .tcd-title { font-size:clamp(28px,3.8vw,44px); font-weight:600; line-height:1.1; letter-spacing:-.03em; margin-bottom:16px; }
  .tcd-sub { font-size:16px; color:#a0b0cb; font-weight:300; max-width:600px; margin:0 auto; line-height:1.6; }

  /* ── les 2 panneaux ── */
  .tcd-versus { display:grid; grid-template-columns:1fr auto 1fr; gap:0; align-items:stretch; }
  .tcd-card { padding:38px 34px 40px; border:1px solid rgba(255,255,255,.10); position:relative; overflow:hidden;
    background:linear-gradient(180deg,rgba(255,255,255,.045),rgba(255,255,255,.012)); }
  .tcd-card--l { border-radius:20px 0 0 20px; border-right:0; }
  .tcd-card--r { border-radius:0 20px 20px 0; border-left:0; }
  .tcd-card::after { content:''; position:absolute; inset:0; pointer-events:none; }
  .tcd-card--l::after { background:radial-gradient(420px 260px at 50% 0%,rgba(77,163,255,.20),transparent 70%); }
  .tcd-card--r::after { background:radial-gradient(420px 260px at 50% 0%,rgba(245,181,68,.18),transparent 70%); }
  .tcd-card > * { position:relative; z-index:2; }
  .tcd-ref { display:inline-block; font-size:10.5px; font-weight:700; letter-spacing:.18em; text-transform:uppercase;
    padding:5px 11px; border-radius:5px; margin-bottom:16px; }
  .tcd-card--l .tcd-ref { color:#8ec6ff; background:rgba(77,163,255,.15); border:1px solid rgba(77,163,255,.32); }
  .tcd-card--r .tcd-ref { color:#ffd27e; background:rgba(245,181,68,.14); border:1px solid rgba(245,181,68,.32); }
  .tcd-name { font-size:30px; font-weight:600; letter-spacing:-.025em; line-height:1.15; margin-bottom:8px; }
  .tcd-for { font-size:14px; color:#9db0cd; font-weight:300; margin-bottom:24px; }
  .tcd-shot { border-radius:15px; overflow:hidden; background:#0b1220; border:1px solid rgba(255,255,255,.08); margin-bottom:26px; }
  .tcd-shot img { width:100%; height:270px; object-fit:cover; display:block; }
  .tcd-screen { display:flex; align-items:baseline; gap:9px; margin-bottom:22px; padding-bottom:22px; border-bottom:1px solid rgba(255,255,255,.09); }
  .tcd-screen b { font-size:42px; font-weight:600; letter-spacing:-.04em; line-height:1; }
  .tcd-card--l .tcd-screen b { color:#7cbcff; } .tcd-card--r .tcd-screen b { color:#ffcd72; }
  .tcd-screen span { font-size:13px; color:#93a5c2; font-weight:300; }
  .tcd-keys { display:flex; flex-direction:column; gap:13px; margin-bottom:28px; }
  .tcd-key { display:flex; gap:11px; align-items:flex-start; font-size:14px; color:#cbd7ea; font-weight:300; line-height:1.45; }
  .tcd-key b { font-weight:600; color:#eaf0fb; }
  .tcd-key svg { width:16px; height:16px; flex:none; margin-top:3px; fill:none; stroke-width:2.4; stroke-linecap:round; stroke-linejoin:round; }
  .tcd-card--l .tcd-key svg { stroke:#4da3ff; } .tcd-card--r .tcd-key svg { stroke:#f5b544; }
  .tcd-foot { display:flex; align-items:center; justify-content:space-between; gap:16px; flex-wrap:wrap; }
  .tcd-price { font-size:13px; color:#93a5c2; font-weight:300; }
  .tcd-price b { display:block; font-size:26px; font-weight:600; color:#fff; letter-spacing:-.02em; }
  .tcd-buy { display:inline-flex; align-items:center; gap:8px; padding:13px 22px; border-radius:9px;
    font-size:13.5px; font-weight:600; text-decoration:none; transition:transform .18s, box-shadow .18s; }
  .tcd-buy:hover { transform:translateY(-2px); }
  .tcd-card--l .tcd-buy { background:linear-gradient(120deg,#2f7bff,#4da3ff); color:#fff; box-shadow:0 10px 26px rgba(47,123,255,.32); }
  .tcd-card--r .tcd-buy { background:linear-gradient(120deg,#e8a02c,#f5b544); color:#25190a; box-shadow:0 10px 26px rgba(245,181,68,.28); }

  .tcd-vs { display:flex; align-items:center; justify-content:center; padding:0 6px; }
  .tcd-vs span { width:56px; height:56px; border-radius:50%; display:flex; align-items:center; justify-content:center;
    background:#05080f; border:1px solid rgba(255,255,255,.16); font-size:12px; font-weight:700;
    letter-spacing:.1em; color:#9fb6da; }

  /* ── tableau comparatif ── */
  .tct { background:#eef1f7; padding:92px 24px; font-family:'Poppins',-apple-system,BlinkMacSystemFont,'Segoe UI',Helvetica,Arial,sans-serif; }
  .tct * { box-sizing:border-box; margin:0; padding:0; }
  .tct-inner { max-width:1000px; margin:0 auto; }
  .tct-eyebrow { font-size:11px; font-weight:600; letter-spacing:.2em; text-transform:uppercase; color:#5b6b86; margin-bottom:14px; }
  .tct-title { font-size:clamp(25px,3.2vw,36px); font-weight:600; color:#0b1220; letter-spacing:-.03em; line-height:1.15; margin-bottom:12px; }
  .tct-sub { font-size:15.5px; color:#5b6b86; font-weight:300; line-height:1.6; margin-bottom:38px; max-width:620px; }
  .tct-scroll { overflow-x:auto; -webkit-overflow-scrolling:touch; border-radius:16px; border:1px solid #dbe1ec; background:#fff; }
  .tct-table { width:100%; border-collapse:collapse; min-width:640px; }
  .tct-table th, .tct-table td { padding:17px 20px; text-align:left; border-bottom:1px solid #eceff5; font-size:14.5px; }
  .tct-table thead th { position:sticky; top:0; background:#fff; padding-top:24px; padding-bottom:20px; border-bottom:2px solid #e4e9f2; }
  .tct-th-label { font-size:11px; font-weight:600; letter-spacing:.16em; text-transform:uppercase; color:#8493ad; }
  .tct-th-model { display:block; font-size:17px; font-weight:600; color:#0b1220; letter-spacing:-.02em; margin-top:5px; }
  .tct-th-model small { display:block; font-size:12px; font-weight:400; color:#7b8aa4; margin-top:3px; letter-spacing:0; }
  .tct-dot { display:inline-block; width:8px; height:8px; border-radius:50%; margin-right:8px; vertical-align:middle; }
  .tct-dot--b { background:#2f7bff; } .tct-dot--g { background:#e8a02c; }
  .tct-table tbody th { font-weight:500; color:#3b4a63; width:34%; background:#fafbfd; }
  .tct-table td { color:#0b1220; font-weight:500; }
  .tct-table tr:last-child th, .tct-table tr:last-child td { border-bottom:0; }
  .tct-win { display:inline-flex; align-items:center; gap:7px; }
  .tct-win svg { width:15px; height:15px; fill:none; stroke:#0f9d63; stroke-width:2.6; stroke-linecap:round; stroke-linejoin:round; }
  .tct-no { color:#98a5ba; font-weight:400; }
  .tct-badge { display:inline-block; font-size:10.5px; font-weight:600; letter-spacing:.06em; text-transform:uppercase;
    padding:3px 8px; border-radius:5px; margin-left:8px; background:rgba(232,160,44,.14); color:#a56d10; }
  .tct-hint { font-size:12.5px; color:#7b8aa4; font-weight:300; margin-top:16px; }

  @media (max-width:900px) {
    .tcd-versus { grid-template-columns:1fr; }
    .tcd-card--l { border-radius:20px 20px 0 0; border-right:1px solid rgba(255,255,255,.10); border-bottom:0; }
    .tcd-card--r { border-radius:0 0 20px 20px; border-left:1px solid rgba(255,255,255,.10); }
    .tcd-vs { padding:0; margin:-28px 0; z-index:5; position:relative; }
    .tcd::before { display:none; }
    .tcd { padding:72px 20px 0; }
    .tct { padding:72px 20px; }
  }
</style>

<section class="tcd" id="tc-duel">
  <div class="tcd-inner">
    <div class="tcd-head">
      <span class="tcd-eyebrow">Touch ou Touch XL</span>
      <h2 class="tcd-title">Deux centrales.<br>Une seule différence qui compte&nbsp;: l'écran.</h2>
      <p class="tcd-sub">Même technologie, mêmes accessoires, même application. Ce qui change, c'est la taille de l'écran, la puissance de la sirène et l'autonomie de la batterie de secours.</p>
    </div>

    <div class="tcd-versus">
      <!-- TOUCH AM301 -->
      <div class="tcd-card tcd-card--l">
        <span class="tcd-ref">AM301 · Touch</span>
        <h3 class="tcd-name">Centrale Touch</h3>
        <p class="tcd-for">Appartement, maison de plain-pied, résidence secondaire</p>
        <div class="tcd-shot">
          <img src="https://cdn.shopify.com/s/files/1/0326/3132/4811/files/8734bc42-ff99-47e9-97d1-34e38b0a4397.jpg?v=1770108612" alt="Centrale d'alarme Daewoo Touch AM301 écran tactile 4,3 pouces" loading="lazy" width="700" height="540">
        </div>
        <div class="tcd-screen"><b>4,3''</b><span>écran tactile couleur</span></div>
        <div class="tcd-keys">
          <div class="tcd-key"><svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg><span>Sirène intégrée <b>95 dB</b></span></div>
          <div class="tcd-key"><svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg><span>Batterie de secours <b>≈ 4 heures</b></span></div>
          <div class="tcd-key"><svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg><span>Wi-Fi 2,4 GHz + <b>GSM 4G en option</b></span></div>
          <div class="tcd-key"><svg viewBox="0 0 24 24"><polyline points="20 6 9 17 4 12"/></svg><span>Format compact, <b>discret dans l'entrée</b></span></div>
        </div>
        <div class="tcd-foot">
          <span class="tcd-price">Pack de départ<b>199,90 €</b></span>
          <a class="tcd-buy" href="https://daewoo-security.fr/products/alarme-daewoo-wifi-gsm-4g-starter-pack-am301?variant=51276200051028">Choisir la Touch →</a>
        </div>
      </div>

      <div class="tcd-vs"><span>VS</span></div>

      <!-- TOUCH XL AM302 -->
      <div class="tcd-card tcd-card--r">
        <span class="tcd-ref">AM302 · Touch XL</span>
        <h3 class="tcd-name">Centrale Touch XL</h3>
        <p class="tcd-for">Grande maison, pavillon sur plusieurs niveaux, villa</p>
        <div class="tcd-shot">
          <img src="https://cdn.shopify.com/s/files/1/0326/3132/4811/files/a294d81e-81d9-4c35-b5a6-9a58f34e5402.jpg?v=1770108612" alt="Centrale d'alarme Daewoo Touch XL AM302 écran tactile 7 pouces" loading="lazy" width="700" height="540">
        </div>
        <div class="tcd-screen"><b>7''</b><span>écran tactile couleur</span></div>
